var call = new LabCall("C1", new LabLine("L1"));
int count = 0;
Action<LabCallEvent> handler = _ => count++;
call.Changed += handler;
call.Changed += handler;
call.Start();
Console.WriteLine(count); // 2
call.Changed -= handler;
Console.WriteLine(call.HandlerCount); // 1
call.Changed -= handler;
Console.WriteLine(call.HandlerCount); // 0

var line = new LabLine("L1");
for (int i = 1; i <= 3; i++)
{
    var call = new LabCall($"C{i}", line);
    using var session = new LabSession(call);
    call.Start(); call.Emit(LabCallState.Active);
    Console.WriteLine(session.Media.Tx(call.Id)); // True
    call.HangUp();
    session.Dispose();
    call.Emit(LabCallState.Ended);
    Console.WriteLine($"handlers={call.HandlerCount} edges={session.Media.EdgeCount} disposals={session.Media.DisposeCount}");
    // 每通 0 0 1
}
